1	/**
2	 * Hermes executor entrypoint — ABI-conformant.
3	 *
4	 * Reads ExecutorInput from environment variables, runs phases 1–5, then
5	 * post-execution (Phase 6) commits, pushes, opens the impl PR, and writes result.json.
6	 *
7	 * Formal ABI env vars (from ExecutorInput):
8	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
9	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH, TASK_REPO_BASE_BRANCH
10	 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
11	 *   RESULT_PATH
12	 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
13	 *
14	 * Hermes-specific env vars (injected via SubProcessAdapterOpts.extraEnv):
15	 *   HERMES_INFERENCE_MODEL    — model ID (e.g. deepseek-v4-flash)
16	 *   HERMES_INFERENCE_PROVIDER — provider (e.g. deepseek)
17	 *   HERMES_MAX_TURNS          — max tool iterations (default 150)
18	 *   RAG_MCP_URL               — optional RAG MCP server URL
19	 *   RAG_MCP_TOKEN             — optional RAG MCP auth token
20	 *   TASK_BRANCH               — mgmt repo branch to check out (default: feature/${featureId}-${taskId})
21	 *
22	 * Startup phases:
23	 *   Phase 1: clone management repo (read-only)
24	 *   Phase 2: clone implementation repo onto TASK_REPO_BRANCH
25	 *   Phase 3: write HERMES_HOME/config.yaml (model + optional MCP stanza)
26	 *   Phase 4: build briefing from mgmt clone
27	 *   Phase 5: spawn hermes chat in try/finally (recovery fires in finally)
28	 *   Phase 6: wrapper commits + pushes + opens impl PR + writes result.json [T4]
29	 */
30	
31	import { spawn, execSync, spawnSync } from "node:child_process";
32	import {
33	  mkdirSync,
34	  writeFileSync,
35	  existsSync,
36	  rmSync,
37	} from "node:fs";
38	import { join, dirname } from "node:path";
39	import { stringify as yamlStringify } from "yaml";
40	import type { ExecutorResult } from "@workflow/runtime-abi";
41	import { runRecovery, parseGitHubCoords, type SpawnResult } from "./recovery.js";
42	import { buildBriefing } from "./briefing.js";
43	import { resolveSSHKey } from "./resolve-ssh-key.js";
44	import { buildGitEnv } from "./git-env.js";
45	
46	// ── Helpers ────────────────────────────────────────────────────────────────────
47	
48	function requireEnv(name: string): string {
49	  const val = process.env[name];
50	  if (!val) throw new Error(`Required env var ${name} is not set`);
51	  return val;
52	}
53	
54	function emit(event: Record<string, unknown>): void {
55	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
56	}
57	
58	function writeResult(resultPath: string, result: ExecutorResult): void {
59	  mkdirSync(dirname(resultPath), { recursive: true });
60	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
61	}
62	
63	// ── Phase 6 helpers ────────────────────────────────────────────────────────────
64	
65	/**
66	 * Stage all changes in repoDir, commit with a conventional message, and push.
67	 * Returns true if a commit was made, false when the working tree was already clean.
68	 */
69	export function commitAndPush(opts: {
70	  repoDir: string;
71	  taskId: string;
72	  featureId: string;
73	  sshKeyPath: string | undefined;
74	  gitAuthorEmail: string;
75	  gitAuthorName: string;
76	}): boolean {
77	  const { repoDir, taskId, featureId, sshKeyPath, gitAuthorEmail, gitAuthorName } = opts;
78	  const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
79	  const execOpts = { env: gitEnv, stdio: "pipe" as const };
80	
81	  execSync(`git -C "${repoDir}" add -A`, execOpts);
82	
83	  const porcelain = execSync(`git -C "${repoDir}" status --porcelain`, {
84	    ...execOpts, encoding: "utf-8",
85	  }).trim();
86	  if (!porcelain) return false;
87	
88	  execSync(
89	    `git -C "${repoDir}" commit -m "feat(${featureId}/${taskId}): hermes agent code changes"`,
90	    execOpts,
91	  );
92	  return true;
93	}
94	
95	export function pushBranch(opts: {
96	  repoDir: string;
97	  branch: string;
98	  sshKeyPath: string | undefined;
99	  gitAuthorEmail: string;
100	  gitAuthorName: string;
101	}): void {
102	  const { repoDir, branch, sshKeyPath, gitAuthorEmail, gitAuthorName } = opts;
103	  execSync(
104	    `git -C "${repoDir}" push origin "${branch}"`,
105	    {
106	      env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
107	      stdio: "pipe" as const,
108	    },
109	  );
110	}
111	
112	/**
113	 * Open an impl PR via the GitHub REST API (curl).
114	 * If a PR already exists for the head branch, returns the existing PR URL.
115	 * Returns the PR html_url on success, throws on failure.
116	 */
117	export function openImplPR(opts: {
118	  taskRepoUrl: string;
119	  featureId: string;
120	  taskId: string;
121	  head: string;
122	  base: string;
123	  githubToken: string;
124	}): string {
125	  const { taskRepoUrl, featureId, taskId, head, base, githubToken } = opts;
126	  const { owner, repo } = parseGitHubCoords(taskRepoUrl);
127	
128	  // Check for an existing open PR on this branch first.
129	  const encodedHead = encodeURIComponent(`${owner}:${head}`);
130	  const listResult = spawnSync("curl", [
131	    "-s",
132	    "-H", `Authorization: token ${githubToken}`,
133	    "-H", "Accept: application/vnd.github+json",
134	    `https://api.github.com/repos/${owner}/${repo}/pulls?head=${encodedHead}&state=open`,
135	  ], { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] });
136	
137	  if (!listResult.error) {
138	    const existing = JSON.parse(listResult.stdout ?? "[]") as Array<{ html_url: string }>;
139	    if (Array.isArray(existing) && existing.length > 0) {
140	      return existing[0].html_url;
141	    }
142	  }
143	
144	  const title = `feat(${featureId}/${taskId}): hermes agent implementation`;
145	  const body = [
146	    `## Task: ${taskId}`,
147	    "",
148	    `**Feature:** ${featureId}`,
149	    `**Branch:** \`${head}\``,
150	    "",
151	    "Implemented by Hermes executor — wrapper opened this PR after agent completed code changes.",
152	  ].join("\n");
153	
154	  const createResult = spawnSync("curl", [
155	    "-s", "-X", "POST",
156	    "-H", `Authorization: token ${githubToken}`,
157	    "-H", "Accept: application/vnd.github+json",
158	    "-H", "Content-Type: application/json",
159	    "-d", JSON.stringify({ title, body, head, base, draft: true }),
160	    `https://api.github.com/repos/${owner}/${repo}/pulls`,
161	  ], { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] });
162	
163	  if (createResult.error) throw createResult.error;
164	
165	  const created = JSON.parse(createResult.stdout ?? "{}") as { html_url?: string };
166	  if (!created.html_url) {
167	    throw new Error(`GitHub PR creation failed: ${createResult.stdout}`);
168	  }
169	  return created.html_url;
170	}
171	
172	// ── Phase 1 + 2: repo materialisation ─────────────────────────────────────────
173	
174	/**
175	 * Clone or pull a repo at targetDir on the given branch.
176	 * If targetDir already contains a valid clone of the same URL,
177	 * fetch + checkout + pull instead of re-cloning.
178	 */
179	export function cloneOrPull(
180	  url: string,
181	  targetDir: string,
182	  branch: string,
183	  sshKeyPath: string | undefined,
184	): void {
185	  const env = buildGitEnv(sshKeyPath);
186	  const opts = { env, stdio: "pipe" as const };
187	
188	  if (existsSync(join(targetDir, ".git"))) {
189	    let originUrl = "";
190	    try {
191	      originUrl = execSync(`git -C "${targetDir}" remote get-url origin`, {
192	        ...opts, encoding: "utf-8",
193	      }).trim();
194	    } catch { /* no remote — fall through to clone */ }
195	
196	    if (originUrl === url) {
197	      execSync(`git -C "${targetDir}" fetch origin`, opts);
198	      try {
199	        execSync(`git -C "${targetDir}" checkout -- .`, opts);
200	      } catch { /* ignore */ }
201	      try {
202	        execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
203	      } catch {
204	        execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
205	      }
206	      try {
207	        execSync(`git -C "${targetDir}" pull --ff-only origin "${branch}"`, opts);
208	      } catch {
209	        emit({ type: "repo_pull_diverged", dir: targetDir, branch, note: "ff-only failed — using checked-out ref" });
210	      }
211	      return;
212	    }
213	  }
214	
215	  mkdirSync(dirname(targetDir), { recursive: true });
216	  if (existsSync(targetDir)) {
217	    rmSync(targetDir, { recursive: true, force: true });
218	  }
219	  execSync(`git clone "${url}" "${targetDir}"`, opts);
220	  try {
221	    execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
222	  } catch {
223	    execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
224	  }
225	}
226	
227	/**
228	 * Materialize the management repo on the task branch.
229	 * Falls back to main if the task branch is not yet on origin.
230	 */
231	export function materializeMgmtRepo(
232	  mgmtRepoUrl: string,
233	  mgmtDir: string,
234	  sshKeyPath: string | undefined,
235	  taskBranch: string,
236	): void {
237	  const env = buildGitEnv(sshKeyPath);
238	  const opts = { env, stdio: "pipe" as const };
239	
240	  const checkoutTaskBranch = (dir: string): void => {
241	    try {
242	      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
243	    } catch (taskBranchErr) {
244	      try {
245	        execSync(`git -C "${dir}" checkout main`, opts);
246	      } catch (e) {
247	        emit({ type: "mgmt_repo_checkout_failed", dir, branch: "main", details: String(e) });
248	      }
249	      try {
250	        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
251	      } catch {
252	        emit({ type: "mgmt_repo_pull_diverged", dir, note: "ff-only failed", task_branch_err: String(taskBranchErr) });
253	      }
254	    }
255	  };
256	
257	  if (existsSync(join(mgmtDir, ".git"))) {
258	    let originUrl = "";
259	    try {
260	      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
261	        ...opts, encoding: "utf-8",
262	      }).trim();
263	    } catch { /* no remote */ }
264	
265	    if (originUrl === mgmtRepoUrl) {
266	      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
267	      checkoutTaskBranch(mgmtDir);
268	      return;
269	    }
270	  }
271	
272	  mkdirSync(dirname(mgmtDir), { recursive: true });
273	  if (existsSync(mgmtDir)) {
274	    rmSync(mgmtDir, { recursive: true, force: true });
275	  }
276	  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
277	  checkoutTaskBranch(mgmtDir);
278	}
279	
280	// ── Phase 3: Hermes config ─────────────────────────────────────────────────────
281	
282	export interface HermesConfig {
283	  provider: string;
284	  model: string;
285	  ragMcpUrl?: string;
286	  ragMcpToken?: string;
287	}
288	
289	/**
290	 * Write HERMES_HOME/config.yaml with model stanza and optional RAG MCP stanza.
291	 * No memory stanza — stateless by default (Mem0 is hermes-workspace-memory scope).
292	 */
293	export function writeHermesConfig(hermesHome: string, config: HermesConfig): void {
294	  mkdirSync(hermesHome, { recursive: true });
295	
296	  const configObj: Record<string, unknown> = {
297	    model: {
298	      provider: config.provider,
299	      default: config.model,
300	    },
301	  };
302	
303	  if (config.ragMcpUrl) {
304	    configObj.mcp_servers = {
305	      rag: {
306	        url: config.ragMcpUrl,
307	        ...(config.ragMcpToken
308	          ? { headers: { Authorization: `Bearer ${config.ragMcpToken}` } }
309	          : {}),
310	      },
311	    };
312	  }
313	
314	  writeFileSync(join(hermesHome, "config.yaml"), yamlStringify(configObj), "utf-8");
315	}
316	
317	// ── Phase 5: Hermes spawn ──────────────────────────────────────────────────────
318	
319	interface HermesSpawnOpts {
320	  briefing: string;
321	  hermesHome: string;
322	  hermesModel: string;
323	  hermesProvider: string;
324	  hermesMaxTurns: string;
325	  taskRepoPath: string;
326	}
327	
328	function spawnHermes(opts: HermesSpawnOpts): Promise<SpawnResult> {
329	  const {
330	    briefing,
331	    hermesHome,
332	    hermesModel,
333	    hermesProvider,
334	    hermesMaxTurns,
335	    taskRepoPath,
336	  } = opts;
337	
338	  return new Promise((resolve) => {
339	    const env: NodeJS.ProcessEnv = {
340	      ...process.env,
341	      HERMES_HOME: hermesHome,
342	      HERMES_INFERENCE_MODEL: hermesModel,
343	      HERMES_INFERENCE_PROVIDER: hermesProvider,
344	      HERMES_MAX_ITERATIONS: hermesMaxTurns,
345	      HERMES_YOLO_MODE: "1",
346	    };
347	
348	    const child = spawn(
349	      "hermes",
350	      ["chat", "--query", briefing, "--quiet", "--ignore-rules"],
351	      {
352	        cwd: taskRepoPath,
353	        env,
354	        stdio: ["ignore", "pipe", "pipe"],
355	      },
356	    );
357	
358	    let stdout = "";
359	    child.stdout.on("data", (chunk: Buffer) => {
360	      stdout += chunk.toString();
361	    });
362	    child.stderr.on("data", (chunk: Buffer) => {
363	      process.stderr.write(chunk);
364	    });
365	
366	    child.on("error", (error: Error) => {
367	      resolve({ stdout, status: null, signal: null, error });
368	    });
369	
370	    child.on("close", (code: number | null, signal: NodeJS.Signals | null) => {
371	      resolve({ stdout, status: code, signal });
372	    });
373	  });
374	}
375	
376	// ── Main ──────────────────────────────────────────────────────────────────────
377	
378	async function main(): Promise<void> {
379	  let taskId: string;
380	  let featureId: string;
381	  let workspaceId: string;
382	  let taskRepoUrl: string;
383	  let taskRepoBranch: string;
384	  let taskBaseBranch: string;
385	  let executorWorkdir: string;
386	  let mgmtRepoUrl: string;
387	  let resultPath: string;
388	  let githubToken: string;
389	  let sshKeyPath: string | undefined;
390	
391	  try {
392	    taskId = requireEnv("TASK_ID");
393	    featureId = requireEnv("FEATURE_ID");
394	    workspaceId = requireEnv("WORKSPACE_ID");
395	    taskRepoUrl = requireEnv("TASK_REPO_URL");
396	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
397	    taskBaseBranch = process.env.TASK_BASE_BRANCH ?? "main";
398	    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
399	    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
400	    resultPath = requireEnv("RESULT_PATH");
401	    githubToken = process.env.GITHUB_TOKEN ?? "";
402	    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }, executorWorkdir).sshKeyPath;
403	  } catch (e) {
404	    emit({ type: "executor_fatal", details: (e as Error).message });
405	    process.exit(1);
406	  }
407	
408	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
409	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
410	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
411	
412	  const hermesModel = process.env.HERMES_INFERENCE_MODEL ?? "default";
413	  const hermesProvider = process.env.HERMES_INFERENCE_PROVIDER ?? "openai";
414	  const hermesMaxTurns = process.env.HERMES_MAX_TURNS ?? "150";
415	  const ragMcpUrl = process.env.RAG_MCP_URL;
416	  const ragMcpToken = process.env.RAG_MCP_TOKEN;
417	
418	  const implDir = join(executorWorkdir, "impl");
419	  const mgmtDir = join(executorWorkdir, "mgmt");
420	  const hermesHome = join(executorWorkdir, "hermes-home");
421	
422	  // Phases 1–4 use terminal_status "failed" (not "blocked") because they are pre-execution
423	  // infrastructure failures — the executor never reached the work phase. The orchestrator
424	  // maps "failed" → blocked/executor_failed. "blocked" is reserved for task-level outcomes
425	  // (no_changes, test failures, etc.) where the executor ran but work could not be completed.
426	
427	  // ── Phase 1: Management repo ───────────────────────────────────────────────
428	  emit({ type: "phase_start", phase: 1, description: "clone management repo" });
429	  try {
430	    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
431	    process.env.WORKSPACE_ROOT = mgmtDir;
432	    emit({ type: "phase_done", phase: 1, mgmt_dir: mgmtDir });
433	  } catch (e) {
434	    emit({ type: "executor_fatal", task_id: taskId, details: `mgmt repo materialization failed: ${String(e)}` });
435	    writeResult(resultPath, {
436	      terminal_status: "failed",
437	      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
438	    });
439	    process.exit(0);
440	  }
441	
442	  // ── Phase 2: Implementation repo ──────────────────────────────────────────
443	  emit({ type: "phase_start", phase: 2, description: "clone implementation repo" });
444	  try {
445	    cloneOrPull(taskRepoUrl, implDir, taskRepoBranch, sshKeyPath);
446	    process.env.TASK_REPO_PATH = implDir;
447	    emit({ type: "phase_done", phase: 2, impl_dir: implDir });
448	  } catch (e) {
449	    emit({ type: "executor_fatal", task_id: taskId, details: `impl repo materialization failed: ${String(e)}` });
450	    writeResult(resultPath, {
451	      terminal_status: "failed",
452	      blocked_reason: `impl_repo_materialization_failed: ${String(e)}`,
453	    });
454	    process.exit(0);
455	  }
456	
457	  // ── Phase 3: Hermes home + config.yaml ────────────────────────────────────
458	  emit({ type: "phase_start", phase: 3, description: "write HERMES_HOME/config.yaml" });
459	  try {
460	    writeHermesConfig(hermesHome, {
461	      provider: hermesProvider,
462	      model: hermesModel,
463	      ragMcpUrl,
464	      ragMcpToken,
465	    });
466	    process.env.HERMES_HOME = hermesHome;
467	    emit({ type: "phase_done", phase: 3, hermes_home: hermesHome });
468	  } catch (e) {
469	    emit({ type: "executor_fatal", task_id: taskId, details: `hermes config write failed: ${String(e)}` });
470	    writeResult(resultPath, {
471	      terminal_status: "failed",
472	      blocked_reason: `hermes_config_write_failed: ${String(e)}`,
473	    });
474	    process.exit(0);
475	  }
476	
477	  // ── Phase 4: Build briefing ────────────────────────────────────────────────
478	  emit({ type: "phase_start", phase: 4, description: "build briefing" });
479	  let briefing: string;
480	  try {
481	    briefing = buildBriefing(mgmtDir, {
482	      workspaceId,
483	      taskId,
484	      featureId,
485	      taskRepoPath: implDir,
486	    });
487	    emit({ type: "phase_done", phase: 4, briefing_length: briefing.length });
488	  } catch (e) {
489	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing build failed: ${String(e)}` });
490	    writeResult(resultPath, {
491	      terminal_status: "failed",
492	      blocked_reason: `briefing_build_failed: ${String(e)}`,
493	    });
494	    process.exit(0);
495	  }
496	
497	  // ── Phase 5: Spawn hermes chat (try/finally for Layer 1 recovery) ──────────
498	  emit({ type: "phase_start", phase: 5, description: "hermes chat spawn" });
499	
500	  let spawnResult: SpawnResult | undefined;
501	
502	  try {
503	    spawnResult = await spawnHermes({
504	      briefing,
505	      hermesHome,
506	      hermesModel,
507	      hermesProvider,
508	      hermesMaxTurns,
509	      taskRepoPath: implDir,
510	    });
511	    emit({
512	      type: "phase_done",
513	      phase: 5,
514	      exit_status: spawnResult.status,
515	      signal: spawnResult.signal ?? null,
516	    });
517	
518	    // ── Phase 6: Post-execution workflow protocol ─────────────────────────────
519	    // On normal Hermes exit: commit, push, open impl PR, write result.json.
520	    // Recovery (finally block) is a no-op when result.json is already written.
521	    emit({ type: "phase_start", phase: 6, description: "post-execution workflow protocol" });
522	
523	    const committed = commitAndPush({
524	      repoDir: implDir,
525	      taskId,
526	      featureId,
527	      sshKeyPath,
528	      gitAuthorEmail,
529	      gitAuthorName,
530	    });
531	
532	    if (!committed) {
533	      // Hermes produced no file changes — treat as blocked.
534	      emit({ type: "phase_6_no_changes", task_id: taskId, feature_id: featureId });
535	      writeResult(resultPath, {
536	        terminal_status: "blocked",
537	        blocked_reason: "no_changes",
538	        blocked_suggestion: "Hermes exited without making any file changes. Re-run with a clearer briefing or more iterations.",
539	      });
540	      return;
541	    }
542	
543	    pushBranch({
544	      repoDir: implDir,
545	      branch: taskRepoBranch,
546	      sshKeyPath,
547	      gitAuthorEmail,
548	      gitAuthorName,
549	    });
550	
551	    const prUrl = openImplPR({
552	      taskRepoUrl,
553	      featureId,
554	      taskId,
555	      head: taskRepoBranch,
556	      base: taskBaseBranch,
557	      githubToken,
558	    });
559	
560	    writeResult(resultPath, { terminal_status: "in_review", pr_url: prUrl });
561	    emit({ type: "phase_done", phase: 6, pr_url: prUrl });
562	
563	  } catch (e) {
564	    // Phase 5 spawn error or Phase 6 workflow protocol error.
565	    emit({ type: "executor_error", task_id: taskId, details: String(e) });
566	    if (!spawnResult) {
567	      spawnResult = { stdout: "", status: null, signal: null, error: e as Error };
568	    }
569	  } finally {
570	    // Layer 1 recovery — fires on any exit from hermes chat, normal or abnormal.
571	    // No-op when Phase 6 already wrote a valid result.json with terminal_status "in_review".
572	    await runRecovery({
573	      spawnResult,
574	      taskId,
575	      featureId,
576	      taskRepoBranch,
577	      taskRepoPath: implDir,
578	      taskRepoUrl,
579	      githubToken,
580	      sshKeyPath,
581	      gitAuthorEmail,
582	      gitAuthorName,
583	      resultPath,
584	      taskBaseBranch,
585	    });
586	  }
587	}
588	
589	// Only run main when this file is the entrypoint (not when imported by tests).
590	import { fileURLToPath } from "node:url";
591	if (process.argv[1] === fileURLToPath(import.meta.url)) {
592	  main().catch((e) => {
593	    console.error(JSON.stringify({ at: new Date().toISOString(), type: "unhandled_error", details: String(e) }));
