1	/**
2	 * Briefing builder for the Hermes executor.
3	 *
4	 * Reads task context from the already-cloned management repo and produces
5	 * a briefing scoped to code work only. The wrapper (index.ts) owns all
6	 * workflow protocol (git, PR, result.json) — Hermes must not attempt any
7	 * of those actions.
8	 */
9	
10	import { readFileSync, existsSync } from "node:fs";
11	import { join } from "node:path";
12	
13	export interface BriefingOpts {
14	  workspaceId: string;
15	  taskId: string;
16	  featureId: string;
17	  taskRepoPath: string;
18	}
19	
20	/**
21	 * Read a section from tasks.md for the given taskId.
22	 * Returns the content between the ## T<n> heading and the next ## heading.
23	 */
24	function readTasksSection(mgmtDir: string, featureId: string, taskId: string): string {
25	  const tasksPath = join(mgmtDir, "docs", "features", featureId, "tasks.md");
26	  if (!existsSync(tasksPath)) return `(tasks.md not found at ${tasksPath})`;
27	
28	  const content = readFileSync(tasksPath, "utf-8");
29	  const lines = content.split("\n");
30	
31	  const startPattern = new RegExp(`^## ${taskId}\\b`);
32	  let startIdx = -1;
33	  for (let i = 0; i < lines.length; i++) {
34	    if (startPattern.test(lines[i])) {
35	      startIdx = i;
36	      break;
37	    }
38	  }
39	
40	  if (startIdx === -1) return `(section ## ${taskId} not found in tasks.md)`;
41	
42	  let endIdx = lines.length;
43	  for (let i = startIdx + 1; i < lines.length; i++) {
44	    if (/^## /.test(lines[i])) {
45	      endIdx = i;
46	      break;
47	    }
48	  }
49	
50	  return lines.slice(startIdx, endIdx).join("\n").trim();
51	}
52	
53	/**
54	 * Read the full task YAML content for the given taskId.
55	 */
56	function readTaskYaml(mgmtDir: string, featureId: string, taskId: string): string {
57	  const yamlPath = join(mgmtDir, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
58	  if (!existsSync(yamlPath)) return `(task YAML not found at ${yamlPath})`;
59	  return readFileSync(yamlPath, "utf-8").trim();
60	}
61	
62	/**
63	 * Read the technical design for the feature.
64	 */
65	function readTechnicalDesign(mgmtDir: string, featureId: string): string {
66	  const tdPath = join(mgmtDir, "docs", "features", featureId, "technical-design.md");
67	  if (!existsSync(tdPath)) return `(technical-design.md not found at ${tdPath})`;
68	  return readFileSync(tdPath, "utf-8").trim();
69	}
70	
71	/**
72	 * Build the briefing string passed to `hermes chat --query`.
73	 *
74	 * Scope: code changes only — no git, no PR, no result.json.
75	 */
76	export function buildBriefing(mgmtDir: string, opts: BriefingOpts): string {
77	  const { workspaceId, taskId, featureId, taskRepoPath } = opts;
78	
79	  const taskYaml = readTaskYaml(mgmtDir, featureId, taskId);
80	  const tasksSection = readTasksSection(mgmtDir, featureId, taskId);
81	  const technicalDesign = readTechnicalDesign(mgmtDir, featureId);
82	
83	  return [
84	    `## Workspace context`,
85	    ``,
86	    `You are an autonomous coding agent working on workspace ${workspaceId}.`,
87	    `Your working directory is ${taskRepoPath}.`,
88	    ``,
89	    `## Task`,
90	    ``,
91	    "```yaml",
92	    taskYaml,
