/**
 * Hermes executor entrypoint — ABI-conformant.
 *
 * Reads ExecutorInput from environment variables, runs phases 1–5, then
 * post-execution (Phase 6) commits, pushes, opens the impl PR, and writes result.json.
 *
 * Formal ABI env vars (from ExecutorInput):
 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH, TASK_REPO_BASE_BRANCH
 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
 *   RESULT_PATH
 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
 *
 * Hermes-specific env vars (injected via SubProcessAdapterOpts.extraEnv):
 *   HERMES_INFERENCE_MODEL    — model ID (e.g. deepseek-v4-flash)
 *   HERMES_INFERENCE_PROVIDER — provider (e.g. deepseek)
 *   HERMES_MAX_TURNS          — max tool iterations (default 150)
 *   RAG_MCP_URL               — optional RAG MCP server URL
 *   RAG_MCP_TOKEN             — optional RAG MCP auth token
 *   TASK_BRANCH               — mgmt repo branch to check out (default: feature/${featureId}-${taskId})
 *
 * Startup phases:
 *   Phase 1: clone management repo (read-only)
 *   Phase 2: clone implementation repo onto TASK_REPO_BRANCH
 *   Phase 3: write HERMES_HOME/config.yaml (model + optional MCP stanza)
 *   Phase 4: build briefing from mgmt clone
 *   Phase 5: spawn hermes chat in try/finally (recovery fires in finally)
 *   Phase 6: wrapper commits + pushes + opens impl PR + writes result.json [T4]
 */

import { spawn, execSync, spawnSync } from "node:child_process";
import {
  mkdirSync,
  writeFileSync,
  existsSync,
  rmSync,
  copyFileSync,
  readdirSync,
  appendFileSync,
} from "node:fs";
import { join, dirname } from "node:path";
import { stringify as yamlStringify } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import { runRecovery, parseGitHubCoords, type SpawnResult } from "./recovery.js";
import { buildBriefing } from "./briefing.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { buildGitEnv } from "./git-env.js";

// ── Helpers ────────────────────────────────────────────────────────────────────

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required env var ${name} is not set`);
  return val;
}

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

function writeResult(resultPath: string, result: ExecutorResult): void {
  mkdirSync(dirname(resultPath), { recursive: true });
  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
}

// ── Phase 6 helpers ────────────────────────────────────────────────────────────

/**
 * Stage all changes in repoDir, commit with a conventional message, and push.
 * Returns true if a commit was made, false when the working tree was already clean.
 */
export function commitAndPush(opts: {
  repoDir: string;
  taskId: string;
  featureId: string;
  sshKeyPath: string | undefined;
  gitAuthorEmail: string;
  gitAuthorName: string;
}): boolean {
  const { repoDir, taskId, featureId, sshKeyPath, gitAuthorEmail, gitAuthorName } = opts;
  const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const execOpts = { env: gitEnv, stdio: "pipe" as const };

  execSync(`git -C "${repoDir}" add -A`, execOpts);

  const porcelain = execSync(`git -C "${repoDir}" status --porcelain`, {
    ...execOpts, encoding: "utf-8",
  }).trim();
  if (!porcelain) return false;

  execSync(
    `git -C "${repoDir}" commit -m "feat(${featureId}/${taskId}): hermes agent code changes"`,
    execOpts,
  );
  return true;
}

export function pushBranch(opts: {
  repoDir: string;
  branch: string;
  sshKeyPath: string | undefined;
  gitAuthorEmail: string;
  gitAuthorName: string;
}): void {
  const { repoDir, branch, sshKeyPath, gitAuthorEmail, gitAuthorName } = opts;
  execSync(
    `git -C "${repoDir}" push origin "${branch}"`,
    {
      env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
      stdio: "pipe" as const,
    },
  );
}

/**
 * Open an impl PR via the GitHub REST API (curl).
 * If a PR already exists for the head branch, returns the existing PR URL.
 * Returns the PR html_url on success, throws on failure.
 */
export function openImplPR(opts: {
  taskRepoUrl: string;
  featureId: string;
  taskId: string;
  head: string;
  base: string;
  githubToken: string;
}): string {
  const { taskRepoUrl, featureId, taskId, head, base, githubToken } = opts;
  const { owner, repo } = parseGitHubCoords(taskRepoUrl);

  // Check for an existing open PR on this branch first.
  const encodedHead = encodeURIComponent(`${owner}:${head}`);
  const listResult = spawnSync("curl", [
    "-s",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    `https://api.github.com/repos/${owner}/${repo}/pulls?head=${encodedHead}&state=open`,
  ], { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] });

  if (!listResult.error) {
    const existing = JSON.parse(listResult.stdout ?? "[]") as Array<{ html_url: string }>;
    if (Array.isArray(existing) && existing.length > 0) {
      return existing[0].html_url;
    }
  }

  const title = `feat(${featureId}/${taskId}): hermes agent implementation`;
  const body = [
    `## Task: ${taskId}`,
    "",
    `**Feature:** ${featureId}`,
    `**Branch:** \`${head}\``,
    "",
    "Implemented by Hermes executor — wrapper opened this PR after agent completed code changes.",
  ].join("\n");

  const createResult = spawnSync("curl", [
    "-s", "-X", "POST",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    "-H", "Content-Type: application/json",
    "-d", JSON.stringify({ title, body, head, base, draft: true }),
    `https://api.github.com/repos/${owner}/${repo}/pulls`,
  ], { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] });

  if (createResult.error) throw createResult.error;

  const created = JSON.parse(createResult.stdout ?? "{}") as { html_url?: string };
  if (!created.html_url) {
    throw new Error(`GitHub PR creation failed: ${createResult.stdout}`);
  }
  return created.html_url;
}

// ── Phase 1 + 2: repo materialisation ─────────────────────────────────────────

/**
 * Clone or pull a repo at targetDir on the given branch.
 * If targetDir already contains a valid clone of the same URL,
 * fetch + checkout + pull instead of re-cloning.
 */
export function cloneOrPull(
  url: string,
  targetDir: string,
  branch: string,
  sshKeyPath: string | undefined,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  if (existsSync(join(targetDir, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${targetDir}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === url) {
      execSync(`git -C "${targetDir}" fetch origin`, opts);
      try {
        execSync(`git -C "${targetDir}" checkout -- .`, opts);
      } catch { /* ignore */ }
      try {
        execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
      } catch {
        execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
      }
      try {
        execSync(`git -C "${targetDir}" pull --ff-only origin "${branch}"`, opts);
      } catch {
        emit({ type: "repo_pull_diverged", dir: targetDir, branch, note: "ff-only failed — using checked-out ref" });
      }
      return;
    }
  }

  mkdirSync(dirname(targetDir), { recursive: true });
  if (existsSync(targetDir)) {
    rmSync(targetDir, { recursive: true, force: true });
  }
  execSync(`git clone "${url}" "${targetDir}"`, opts);
  try {
    execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
  } catch {
    execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
  }
}

/**
 * Materialize the management repo on the task branch.
 * Falls back to main if the task branch is not yet on origin.
 */
export function materializeMgmtRepo(
  mgmtRepoUrl: string,
  mgmtDir: string,
  sshKeyPath: string | undefined,
  taskBranch: string,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  const checkoutTaskBranch = (dir: string): void => {
    try {
      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
    } catch (taskBranchErr) {
      try {
        execSync(`git -C "${dir}" checkout main`, opts);
      } catch (e) {
        emit({ type: "mgmt_repo_checkout_failed", dir, branch: "main", details: String(e) });
      }
      try {
        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
      } catch {
        emit({ type: "mgmt_repo_pull_diverged", dir, note: "ff-only failed", task_branch_err: String(taskBranchErr) });
      }
    }
  };

  if (existsSync(join(mgmtDir, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote */ }

    if (originUrl === mgmtRepoUrl) {
      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
      checkoutTaskBranch(mgmtDir);
      return;
    }
  }

  mkdirSync(dirname(mgmtDir), { recursive: true });
  if (existsSync(mgmtDir)) {
    rmSync(mgmtDir, { recursive: true, force: true });
  }
  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
  checkoutTaskBranch(mgmtDir);
}

// ── Phase 3: Hermes config ─────────────────────────────────────────────────────

export interface HermesConfig {
  provider: string;
  model: string;
  ragMcpUrl?: string;
  ragMcpToken?: string;
}

/**
 * Write HERMES_HOME/config.yaml with model stanza and optional RAG MCP stanza.
 * No memory stanza — stateless by default (Mem0 is hermes-workspace-memory scope).
 */
export function writeHermesConfig(hermesHome: string, config: HermesConfig): void {
  mkdirSync(hermesHome, { recursive: true });

  const configObj: Record<string, unknown> = {
    model: {
      provider: config.provider,
      default: config.model,
    },
  };

  if (config.ragMcpUrl) {
    configObj.mcp_servers = {
      rag: {
        url: config.ragMcpUrl,
        ...(config.ragMcpToken
          ? { headers: { Authorization: `Bearer ${config.ragMcpToken}` } }
          : {}),
      },
    };
  }

  writeFileSync(join(hermesHome, "config.yaml"), yamlStringify(configObj), "utf-8");
}

// ── Phase 5: Hermes spawn ──────────────────────────────────────────────────────

interface HermesSpawnOpts {
  briefing: string;
  hermesHome: string;
  hermesModel: string;
  hermesProvider: string;
  hermesMaxTurns: string;
  taskRepoPath: string;
}

function spawnHermes(opts: HermesSpawnOpts): Promise<SpawnResult> {
  const {
    briefing,
    hermesHome,
    hermesModel,
    hermesProvider,
    hermesMaxTurns,
    taskRepoPath,
  } = opts;

  return new Promise((resolve) => {
    const env: NodeJS.ProcessEnv = {
      ...process.env,
      HERMES_HOME: hermesHome,
      HERMES_INFERENCE_MODEL: hermesModel,
      HERMES_INFERENCE_PROVIDER: hermesProvider,
      HERMES_MAX_ITERATIONS: hermesMaxTurns,
      HERMES_YOLO_MODE: "1",
    };

    const child = spawn(
      "hermes",
      ["chat", "--query", briefing, "--quiet", "--ignore-rules"],
      {
        cwd: taskRepoPath,
        env,
        stdio: ["ignore", "pipe", "pipe"],
      },
    );

    let stdout = "";
    child.stdout.on("data", (chunk: Buffer) => {
      stdout += chunk.toString();
    });
    child.stderr.on("data", (chunk: Buffer) => {
      process.stderr.write(chunk);
    });

    child.on("error", (error: Error) => {
      resolve({ stdout, status: null, signal: null, error });
    });

    child.on("close", (code: number | null, signal: NodeJS.Signals | null) => {
      resolve({ stdout, status: code, signal });
    });
  });
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  let taskId: string;
  let featureId: string;
  let workspaceId: string;
  let taskRepoUrl: string;
  let taskRepoBranch: string;
  let taskBaseBranch: string;
  let executorWorkdir: string;
  let mgmtRepoUrl: string;
  let resultPath: string;
  let githubToken: string;
  let sshKeyPath: string | undefined;

  try {
    taskId = requireEnv("TASK_ID");
    featureId = requireEnv("FEATURE_ID");
    workspaceId = requireEnv("WORKSPACE_ID");
    taskRepoUrl = requireEnv("TASK_REPO_URL");
    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
    taskBaseBranch = process.env.TASK_BASE_BRANCH ?? "main";
    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
    resultPath = requireEnv("RESULT_PATH");
    githubToken = process.env.GITHUB_TOKEN ?? "";
    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }, executorWorkdir).sshKeyPath;
  } catch (e) {
    emit({ type: "executor_fatal", details: (e as Error).message });
    process.exit(1);
  }

  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;

  const hermesModel = process.env.HERMES_INFERENCE_MODEL ?? "default";
  const hermesProvider = process.env.HERMES_INFERENCE_PROVIDER ?? "openai";
  const hermesMaxTurns = process.env.HERMES_MAX_TURNS ?? "150";
  const ragMcpUrl = process.env.RAG_MCP_URL;
  const ragMcpToken = process.env.RAG_MCP_TOKEN;

  const implDir = join(executorWorkdir, "impl");
  const mgmtDir = join(executorWorkdir, "mgmt");
  const hermesHome = join(executorWorkdir, "hermes-home");

  // Phases 1–4 use terminal_status "failed" (not "blocked") because they are pre-execution
  // infrastructure failures — the executor never reached the work phase. The orchestrator
  // maps "failed" → blocked/executor_failed. "blocked" is reserved for task-level outcomes
  // (no_changes, test failures, etc.) where the executor ran but work could not be completed.

  // ── Phase 1: Management repo ───────────────────────────────────────────────
  emit({ type: "phase_start", phase: 1, description: "clone management repo" });
  try {
    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
    process.env.WORKSPACE_ROOT = mgmtDir;
    emit({ type: "phase_done", phase: 1, mgmt_dir: mgmtDir });
  } catch (e) {
    emit({ type: "executor_fatal", task_id: taskId, details: `mgmt repo materialization failed: ${String(e)}` });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // ── Phase 2: Implementation repo ──────────────────────────────────────────
  emit({ type: "phase_start", phase: 2, description: "clone implementation repo" });
  try {
    cloneOrPull(taskRepoUrl, implDir, taskRepoBranch, sshKeyPath);
    process.env.TASK_REPO_PATH = implDir;
    emit({ type: "phase_done", phase: 2, impl_dir: implDir });
  } catch (e) {
    emit({ type: "executor_fatal", task_id: taskId, details: `impl repo materialization failed: ${String(e)}` });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `impl_repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // ── Phase 3: Hermes home + config.yaml ────────────────────────────────────
  emit({ type: "phase_start", phase: 3, description: "write HERMES_HOME/config.yaml" });
  try {
    writeHermesConfig(hermesHome, {
      provider: hermesProvider,
      model: hermesModel,
      ragMcpUrl,
      ragMcpToken,
    });
    process.env.HERMES_HOME = hermesHome;
    emit({ type: "phase_done", phase: 3, hermes_home: hermesHome });
  } catch (e) {
    emit({ type: "executor_fatal", task_id: taskId, details: `hermes config write failed: ${String(e)}` });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `hermes_config_write_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // ── Phase 4: Build briefing ────────────────────────────────────────────────
  emit({ type: "phase_start", phase: 4, description: "build briefing" });
  let briefing: string;
  try {
    briefing = buildBriefing(mgmtDir, {
      workspaceId,
      taskId,
      featureId,
      taskRepoPath: implDir,
    });
    emit({ type: "phase_done", phase: 4, briefing_length: briefing.length });
  } catch (e) {
    emit({ type: "executor_fatal", task_id: taskId, details: `briefing build failed: ${String(e)}` });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `briefing_build_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // ── Phase 5: Spawn hermes chat (try/finally for Layer 1 recovery) ──────────
  emit({ type: "phase_start", phase: 5, description: "hermes chat spawn" });

  let spawnResult: SpawnResult | undefined;

  try {
    spawnResult = await spawnHermes({
      briefing,
      hermesHome,
      hermesModel,
      hermesProvider,
      hermesMaxTurns,
      taskRepoPath: implDir,
    });
    emit({
      type: "phase_done",
      phase: 5,
      exit_status: spawnResult.status,
      signal: spawnResult.signal ?? null,
    });

    // ── Phase 6: Post-execution workflow protocol ─────────────────────────────
    // On normal Hermes exit: commit, push, open impl PR, write result.json.
    // Recovery (finally block) is a no-op when result.json is already written.
    emit({ type: "phase_start", phase: 6, description: "post-execution workflow protocol" });

    const committed = commitAndPush({
      repoDir: implDir,
      taskId,
      featureId,
      sshKeyPath,
      gitAuthorEmail,
      gitAuthorName,
    });

    if (!committed) {
      // Hermes produced no file changes — treat as blocked.
      emit({ type: "phase_6_no_changes", task_id: taskId, feature_id: featureId });
      writeResult(resultPath, {
        terminal_status: "blocked",
        blocked_reason: "no_changes",
        blocked_suggestion: "Hermes exited without making any file changes. Re-run with a clearer briefing or more iterations.",
      });
      return;
    }

    pushBranch({
      repoDir: implDir,
      branch: taskRepoBranch,
      sshKeyPath,
      gitAuthorEmail,
      gitAuthorName,
    });

    const prUrl = openImplPR({
      taskRepoUrl,
      featureId,
      taskId,
      head: taskRepoBranch,
      base: taskBaseBranch,
      githubToken,
    });

    writeResult(resultPath, { terminal_status: "in_review", pr_url: prUrl });
    emit({ type: "phase_done", phase: 6, pr_url: prUrl });

  } catch (e) {
    // Phase 5 spawn error or Phase 6 workflow protocol error.
    emit({ type: "executor_error", task_id: taskId, details: String(e) });
    if (!spawnResult) {
      spawnResult = { stdout: "", status: null, signal: null, error: e as Error };
    }
  } finally {
    // Layer 1 recovery — fires on any exit from hermes chat, normal or abnormal.
    // No-op when Phase 6 already wrote a valid result.json with terminal_status "in_review".
    await runRecovery({
      spawnResult,
      taskId,
      featureId,
      taskRepoBranch,
      taskRepoPath: implDir,
      taskRepoUrl,
      githubToken,
      sshKeyPath,
      gitAuthorEmail,
      gitAuthorName,
      resultPath,
      taskBaseBranch,
    });
  }
}

// Only run main when this file is the entrypoint (not when imported by tests).
import { fileURLToPath } from "node:url";
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((e) => {
    console.error(JSON.stringify({ at: new Date().toISOString(), type: "unhandled_error", details: String(e) }));
    process.exit(1);
  });
}

