/**
 * Briefing builder for the Hermes executor.
 *
 * Reads task context from the already-cloned management repo and produces
 * a briefing scoped to code work only. The wrapper (index.ts) owns all
 * workflow protocol (git, PR, result.json) — Hermes must not attempt any
 * of those actions.
 */

import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";

export interface BriefingOpts {
  workspaceId: string;
  taskId: string;
  featureId: string;
  taskRepoPath: string;
}

/**
 * Read a section from tasks.md for the given taskId.
 * Returns the content between the ## T<n> heading and the next ## heading.
 */
function readTasksSection(mgmtDir: string, featureId: string, taskId: string): string {
  const tasksPath = join(mgmtDir, "docs", "features", featureId, "tasks.md");
  if (!existsSync(tasksPath)) return `(tasks.md not found at ${tasksPath})`;

  const content = readFileSync(tasksPath, "utf-8");
  const lines = content.split("\n");

  const startPattern = new RegExp(`^## ${taskId}\\b`);
  let startIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (startPattern.test(lines[i])) {
      startIdx = i;
      break;
    }
  }

  if (startIdx === -1) return `(section ## ${taskId} not found in tasks.md)`;

  let endIdx = lines.length;
  for (let i = startIdx + 1; i < lines.length; i++) {
    if (/^## /.test(lines[i])) {
      endIdx = i;
      break;
    }
  }

  return lines.slice(startIdx, endIdx).join("\n").trim();
}

/**
 * Read the full task YAML content for the given taskId.
 */
function readTaskYaml(mgmtDir: string, featureId: string, taskId: string): string {
  const yamlPath = join(mgmtDir, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
  if (!existsSync(yamlPath)) return `(task YAML not found at ${yamlPath})`;
  return readFileSync(yamlPath, "utf-8").trim();
}

/**
 * Read the technical design for the feature.
 */
function readTechnicalDesign(mgmtDir: string, featureId: string): string {
  const tdPath = join(mgmtDir, "docs", "features", featureId, "technical-design.md");
  if (!existsSync(tdPath)) return `(technical-design.md not found at ${tdPath})`;
  return readFileSync(tdPath, "utf-8").trim();
}

/**
 * Build the briefing string passed to `hermes chat --query`.
 *
 * Scope: code changes only — no git, no PR, no result.json.
 */
export function buildBriefing(mgmtDir: string, opts: BriefingOpts): string {
  const { workspaceId, taskId, featureId, taskRepoPath } = opts;

  const taskYaml = readTaskYaml(mgmtDir, featureId, taskId);
  const tasksSection = readTasksSection(mgmtDir, featureId, taskId);
  const technicalDesign = readTechnicalDesign(mgmtDir, featureId);

  return [
    `## Workspace context`,
    ``,
    `You are an autonomous coding agent working on workspace ${workspaceId}.`,
    `Your working directory is ${taskRepoPath}.`,
    ``,
    `## Task`,
    ``,
    "```yaml",
    taskYaml,
    "```",
    ``,
    `## Description and subtasks`,
    ``,
    tasksSection,
    ``,
    `## Technical design`,
    ``,
    technicalDesign,
    ``,
    `## Your scope`,
    ``,
    `Make the required code changes and save the files. Do not commit, push, open a pull`,
    `request, or write any result file — those steps are handled outside your session.`,
    `When your changes are saved, you are done.`,
  ].join("\n");
}

