/**
 * Scan ~/.hermes/skills/ for slash commands and return a formatted index.
 * Returns an empty string when the skills directory does not exist.
 */
export function buildAvailableSkillsIndex(hermesHome: string): string {
  const skillsDir = join(hermesHome, "skills");
  if (!existsSync(skillsDir)) return "";

  let entries: string[] = [];
  try {
    entries = readdirSync(skillsDir);
  } catch {
    return "";
  }

  if (entries.length === 0) return "";

  const lines = ["## Available skills", ""];
  for (const name of entries.sort()) {
    lines.push(`- /${name}`);
  }
  return lines.join("\n");
}

/**
 * Build the briefing string passed to `hermes chat --query`.
 *
 * Scope: code changes + incremental commits — no push, no PR, no result.json.
 */
export function buildBriefing(mgmtDir: string, opts: BriefingOpts): string {
  const { workspaceId, taskId, featureId, taskRepoPath, hermesHome } = opts;

  const taskYaml = readTaskYaml(mgmtDir, featureId, taskId);
  const tasksSection = readTasksSection(mgmtDir, featureId, taskId);
  const technicalDesign = readTechnicalDesign(mgmtDir, featureId);

  const skillsIndex = hermesHome ? buildAvailableSkillsIndex(hermesHome) : "";

  const parts = [
    `## Workspace context`,
    ``,
    `You are an autonomous coding agent working on workspace ${workspaceId}.`,
    `Your working directory is ${taskRepoPath}.`,
    ``,
    `## Task`,
    ``,
    "```yaml",
    taskYaml,
    "```",
    ``,
    `## Description and subtasks`,
    ``,
    tasksSection,
    ``,
    `## Technical design`,
    ``,
    technicalDesign,
    ``,
  ];

  if (skillsIndex) {
    parts.push(skillsIndex, ``);
  }

  parts.push(
    `## Your scope`,
    ``,
    `Make the required code changes and commit them incrementally with`,
    `\`feat(<featureId>/<taskId>): <what>\` messages. Run the project's test`,
    `suite before you stop. Do NOT run \`git push\`, do NOT open a pull`,
    `request, do NOT write any result file — the wrapper handles those`,
    `steps after you exit.`,
  );

  return parts.join("\n");
}

