import { describe, it, expect, beforeEach, afterEach } from "vitest";
import {
  mkdirSync,
  writeFileSync,
  readFileSync,
  existsSync,
  rmSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { copyDirRecursive, runPhase35 } from "./index.js";

// ── copyDirRecursive unit tests ────────────────────────────────────────────────

describe("copyDirRecursive", () => {
  let base: string;

  beforeEach(() => {
    base = join(tmpdir(), `copy-dir-test-${Date.now()}`);
    mkdirSync(base, { recursive: true });
  });

  afterEach(() => {
    rmSync(base, { recursive: true, force: true });
  });

  it("copies a flat directory", () => {
    const src = join(base, "src");
    mkdirSync(src);
    writeFileSync(join(src, "file.txt"), "hello", "utf-8");

    const dest = join(base, "dest");
    copyDirRecursive(src, dest);

    expect(existsSync(join(dest, "file.txt"))).toBe(true);
    expect(readFileSync(join(dest, "file.txt"), "utf-8")).toBe("hello");
  });

  it("copies nested directories recursively", () => {
    const src = join(base, "src");
    mkdirSync(join(src, "sub"), { recursive: true });
    writeFileSync(join(src, "top.txt"), "top", "utf-8");
    writeFileSync(join(src, "sub", "nested.txt"), "nested", "utf-8");

    const dest = join(base, "dest");
    copyDirRecursive(src, dest);

    expect(readFileSync(join(dest, "top.txt"), "utf-8")).toBe("top");
    expect(readFileSync(join(dest, "sub", "nested.txt"), "utf-8")).toBe("nested");
  });

  it("creates destination directory if it does not exist", () => {
    const src = join(base, "src");
    mkdirSync(src);
    writeFileSync(join(src, "a.txt"), "a", "utf-8");

    const dest = join(base, "new", "nested", "dest");
    copyDirRecursive(src, dest);

    expect(existsSync(dest)).toBe(true);
    expect(existsSync(join(dest, "a.txt"))).toBe(true);
  });
});

// ── Phase 3.5 integration tests ───────────────────────────────────────────────

describe("Phase 3.5 — Hermes context + skill staging", () => {
  let base: string;
  let workflowLocalPath: string;
  let hermesHome: string;
  let mgmtDir: string;
  let implDir: string;

  beforeEach(() => {
    base = join(tmpdir(), `phase35-test-${Date.now()}`);

    // Workflow repo layout
    workflowLocalPath = join(base, "workflow");
    const hermesSrc = join(workflowLocalPath, "hermes");
    mkdirSync(join(hermesSrc, "workflow_skills", "start-implementation"), { recursive: true });
    mkdirSync(join(hermesSrc, "technical_skills", "typescript-best-practices"), { recursive: true });
    writeFileSync(join(hermesSrc, "SOUL.md"), "# SOUL", "utf-8");
    writeFileSync(
      join(hermesSrc, "workflow_skills", "start-implementation", "SKILL.md"),
      "# start-implementation skill",
      "utf-8",
    );
    writeFileSync(
      join(hermesSrc, "technical_skills", "typescript-best-practices", "SKILL.md"),
      "# typescript best practices",
      "utf-8",
    );

    // Hermes home (staging area)
    hermesHome = join(base, "hermes-home");
    mkdirSync(hermesHome, { recursive: true });

    // Management repo clone (contains workspace HERMES.md after sync-workspace-rules)
    mgmtDir = join(base, "mgmt");
    mkdirSync(mgmtDir, { recursive: true });
    writeFileSync(join(mgmtDir, "HERMES.md"), "# workspace hermes rules", "utf-8");

    // Implementation repo clone (has .git/info/exclude)
    implDir = join(base, "impl");
    mkdirSync(join(implDir, ".git", "info"), { recursive: true });
    writeFileSync(join(implDir, ".git", "info", "exclude"), "# git exclude\n", "utf-8");
  });

  afterEach(() => {
