function runPhase35(opts: {
  workflowLocalPath: string;
  hermesHome: string;
  mgmtDir: string;
  implDir: string;
}): { soulCopied: boolean; skillsCopied: string[]; hermesMdCopied: boolean; excludeUpdated: boolean } {
  const { workflowLocalPath, hermesHome, mgmtDir, implDir } = opts;
  const {
    existsSync: fsExists,
    copyFileSync,
    mkdirSync: fsMkdir,
    rmSync: fsRm,
    readdirSync,
    appendFileSync,
  } = require("node:fs") as typeof import("node:fs");
  const { join: pathJoin, dirname } = require("node:path") as typeof import("node:path");
  const { copyDirRecursive: cpDir } = require("./index.js") as typeof import("./index.js");

  const result = { soulCopied: false, skillsCopied: [] as string[], hermesMdCopied: false, excludeUpdated: false };

  if (!workflowLocalPath) return result;

  const hermesSrc = pathJoin(workflowLocalPath, "hermes");

  // 3.5a
  const soulSrc = pathJoin(hermesSrc, "SOUL.md");
  if (fsExists(soulSrc)) {
    copyFileSync(soulSrc, pathJoin(hermesHome, "SOUL.md"));
    result.soulCopied = true;
  }

  // 3.5b
  const targetSkillsDir = pathJoin(hermesHome, "skills");
  if (fsExists(targetSkillsDir)) fsRm(targetSkillsDir, { recursive: true, force: true });
  fsMkdir(targetSkillsDir, { recursive: true });
  for (const srcName of ["workflow_skills", "technical_skills"]) {
    const src = pathJoin(hermesSrc, srcName);
    if (fsExists(src)) {
      for (const entry of readdirSync(src)) {
        cpDir(pathJoin(src, entry), pathJoin(targetSkillsDir, entry));
        result.skillsCopied.push(entry);
      }
    }
  }

  // 3.5c
  const workspaceHermesMd = pathJoin(mgmtDir, "HERMES.md");
  if (fsExists(workspaceHermesMd)) {
    copyFileSync(workspaceHermesMd, pathJoin(implDir, "HERMES.md"));
    result.hermesMdCopied = true;

    // 3.5d
    const excludePath = pathJoin(implDir, ".git", "info", "exclude");
    if (fsExists(dirname(excludePath))) {
      appendFileSync(excludePath, "\n# Hermes auto-loaded workspace rules (local-only)\nHERMES.md\n");
      result.excludeUpdated = true;
    }
  }

  return result;
}

